/// The catalog name DuckDB sees in `ATTACH 'mask' (TYPE vgi, …)`. Defaults to
/// `mask`, but honors an explicit `VGI_WORKER_CATALOG_NAME` override so a test
/// harness can rename it.
pub fn catalog_name() -> String {
    if std::env::var_os("VGI_WORKER_CATALOG_NAME").is_none() {
        std::env::set_var("VGI_WORKER_CATALOG_NAME", "mask");
    }
    std::env::var("VGI_WORKER_CATALOG_NAME").unwrap_or_else(|_| "mask".to_string())
}

/// Build the fully-registered `mask` worker: every scalar function plus catalog
/// metadata. Shared verbatim by the native binary (`main.rs`, which calls
/// `.run()`) and the wasm entrypoint (`mask-wasm`, which serves it over a byte
/// channel). Does NOT start any transport — the caller chooses that.
pub fn build_worker() -> Worker {
    let name = catalog_name();
    let mut worker = Worker::new();
    scalar::register(&mut worker);
    worker.set_catalog(catalog_metadata(&name));
    worker

